CREATE TABLE IF NOT EXISTS cinema_bookings (  booking_id INTEGER PRIMARY KEY AUTOINCREMENT,  showing_id INTEGER NOT NULL,  user_id TEXT NOT NULL,  seats INTEGER DEFAULT 1,  total_price REAL,  booking_date TEXT DEFAULT (datetime('now')),  status TEXT DEFAULT 'booked', "booking_ref" TEXT, "user_name" TEXT, "user_email" TEXT, "screening_id" INTEGER, "movie_title" TEXT, "screening_date" DATE, "screening_time" TEXT, "num_tickets" INTEGER, "ticket_type" TEXT, "seat_numbers" TEXT, "ticket_total" REAL, "snacks_total" REAL DEFAULT 0.00, "member_discount" REAL DEFAULT 0.00, "total_amount" REAL, "payment_method" TEXT, "points_earned" INTEGER DEFAULT 0, "points_redeemed" INTEGER DEFAULT 0,  FOREIGN KEY (showing_id) REFERENCES cinema_showings (id));
